// Prepare sections - map outline sections to their chunk text
const input = $input.first().json;
const outline = (input.analyst_result || {}).outline || [];
const chunkMapping = (input.analyst_result || {}).chunk_mapping || {};
const chunks = input.chunks || [];
const jobId = input.job_id || '';
const prompt = input.prompt || '';

// If no chunks provided, use the prompt as the source text
const effectiveChunks = chunks.length > 0 ? chunks : [prompt];

const sections = [];
for (const section of outline) {
  const sectionId = String(section.section_id || 0);
  const mappedChunkIds = chunkMapping[sectionId] || [];

  let sectionTextParts = [];
  for (const cid of mappedChunkIds) {
    const idx = parseInt(cid);
    if (idx >= 0 && idx < effectiveChunks.length) {
      sectionTextParts.push(effectiveChunks[idx]);
    }
  }

  // If no mapping, assign based on position
  if (sectionTextParts.length === 0) {
    const totalSections = outline.length;
    const totalChunks = effectiveChunks.length;
    if (totalChunks > 0 && totalSections > 0) {
      const start = Math.floor(parseInt(sectionId) * totalChunks / totalSections);
      const end = Math.floor((parseInt(sectionId) + 1) * totalChunks / totalSections);
      sectionTextParts = effectiveChunks.slice(start, Math.max(start + 1, end));
    }
  }

  const sectionText = sectionTextParts.join('\n\n');
  sections.push({
    section_id: section.section_id || 0,
    section_title: section.title || '',
    num_slides: section.slides || 2,
    key_points: section.key_points || [],
    section_text: sectionText,
    chunk_ids: mappedChunkIds,
    text_word_count: sectionText.split(' ').length,
  });
}

return [{
  json: {
    job_id: jobId,
    sections: sections
  }
}];

// Parse LLM response → slides array
const response = $input.first().json;
let text = response.output || '[]';
text = text.replace(/<think>[\s\S]*?<\/think>/g, "").trim();

try {
  const slides = JSON.parse(text.replace(/```json\n?|```/g, ""));
  return [{ json: { section_slides: Array.isArray(slides) ? slides : [slides] } }];
} catch (e) {
  // Try to extract JSON from text
  const match = text.match(/\[[\s\S]*\]/);
  if (match) {
    try {
      return [{ json: { section_slides: JSON.parse(match[0]) } }];
    } catch (e2) {}
  }
  return [{ json: { section_slides: [], parse_error: e.message } }];
}

// Merge and renumber slides from all sections
const input = $input.first().json;
const allSectionSlides = input.data || input || [];
const jobId = $('Agent: Prepare Sections').first().json.job_id || '';

let allSlides = [];
if (Array.isArray(allSectionSlides)) {
  for (const sectionData of allSectionSlides) {
    const sectionSlides = sectionData.section_slides || sectionData.slides || [];
    if (Array.isArray(sectionSlides)) {
      allSlides.push(...sectionSlides);
    }
  }
}

// Deduplicate by title
const seenTitles = new Set();
const uniqueSlides = [];
for (const slide of allSlides) {
  const title = (slide.title || '').trim().toLowerCase();
  if (title && seenTitles.has(title)) continue;
  if (title) seenTitles.add(title);
  uniqueSlides.push(slide);
}

// Renumber
for (let i = 0; i < uniqueSlides.length; i++) {
  uniqueSlides[i].slide_number = i + 1;
}

return [{
  json: {
    job_id: jobId,
    slides: uniqueSlides,
    total_slides: uniqueSlides.length
  }
}];

// Prepare output for next pipeline
const merged = $input.first().json;
return [{
  json: {
    job_id: $('Start').first().json.job_id,
    slides: merged.slides,
    total_slides: merged.total_slides,
    output_format: $('Start').first().json.output_format,
    context: $('Start').first().json.analyst_result
  }
}];
